const FACTORS = {
car: 170.0,
car_shared: 85.0,
train: 35.7,
subway: 27.3,
bus: 89.0,
tram: 28.9,
bicycle: 0.0,
e_bicycle: 4.5,
walking: 0.0,
motorcycle: 103.0,
ev_car: 47.0,
taxi: 186.0,
flight_domestic: 246.0,
flight_short_haul: 151.0,
ferry: 18.9
};

// Read the CSV binary safely from the previous Read CSV node
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
let csvText = buffer.toString('utf8');

// Remove UTF-8 BOM and surrounding whitespace
csvText = csvText.replace(/^\uFEFF/, '').trim();

if (!csvText) {
throw new Error('CSV file is empty');
}

function parseDate(value) {
const input = String(value || '').trim();
let date;

// DD-MM-YYYY
if (/^\d{2}-\d{2}-\d{4}$/.test(input)) {
const [day, month, year] = input.split('-').map(Number);
date = new Date(Date.UTC(year, month - 1, day));
}

// YYYY-MM-DD
else if (/^\d{4}-\d{2}-\d{2}$/.test(input)) {
const [year, month, day] = input.split('-').map(Number);
date = new Date(Date.UTC(year, month - 1, day));
}

else {
throw new Error(`Unsupported date format: ${input}`);
}

if (Number.isNaN(date.getTime())) {
throw new Error(`Invalid date: ${input}`);
}

return date;
}

function getIsoWeek(date) {
const workingDate = new Date(date);
const day = workingDate.getUTCDay() || 7;

workingDate.setUTCDate(
workingDate.getUTCDate() + 4 - day
);

const yearStart = new Date(
Date.UTC(workingDate.getUTCFullYear(), 0, 1)
);

return Math.ceil(
(((workingDate - yearStart) / 86400000) + 1) / 7
);
}

// Split CSV into rows
const lines = csvText.split(/\r?\n/);

if (lines.length < 2) {
throw new Error('CSV contains no data rows');
}

// Clean header names, including BOM and quotation marks
const headers = lines[0]
.replace(/^\uFEFF/, '')
.split(',')
.map(header =>
header
.trim()
.replace(/^"|"$/g, '')
);

const requiredColumns = [
'persona_id',
'date',
'transport_mode',
'distance_km',
'origin',
'destination'
];

for (const column of requiredColumns) {
if (!headers.includes(column)) {
throw new Error(
`Missing CSV column: ${column}. Found headers: ${headers.join(', ')}`
);
}
}

const records = [];
const rejectedRows = [];

for (let rowIndex = 1; rowIndex < lines.length; rowIndex++) {
const line = lines[rowIndex].trim();

if (!line) {
continue;
}

const values = line
.split(',')
.map(value =>
value
.trim()
.replace(/^"|"$/g, '')
);

const row = {};

headers.forEach((header, index) => {
row[header] = values[index] ?? '';
});

const mode = String(row.transport_mode || '')
.trim()
.toLowerCase();

const distance = Number(row.distance_km);

if (!mode || !(mode in FACTORS)) {
rejectedRows.push({
row_number: rowIndex + 1,
reason: `Unsupported transport mode: ${mode}`,
row
});
continue;
}

if (!Number.isFinite(distance) || distance < 0) {
rejectedRows.push({
row_number: rowIndex + 1,
reason: `Invalid distance: ${row.distance_km}`,
row
});
continue;
}

let parsedDate;

try {
parsedDate = parseDate(row.date);
} catch (error) {
rejectedRows.push({
row_number: rowIndex + 1,
reason: error.message,
row
});
continue;
}

const factor = FACTORS[mode];
const co2eGrams = Math.round(
distance * factor * 100
) / 100;

records.push({
persona_id: row.persona_id,
date: parsedDate.toISOString().slice(0, 10),
original_date: row.date,
week_number: getIsoWeek(parsedDate),
transport_mode: mode,
distance_km: distance,
factor_g_per_km: factor,
co2e_grams: co2eGrams,
origin: row.origin || '',
destination: row.destination || ''
});
}

if (!records.length) {
throw new Error(
`No valid records after parsing. Rejected rows: ${rejectedRows.length}`
);
}

console.log(`Valid records: ${records.length}`);
console.log(`Rejected rows: ${rejectedRows.length}`);

return records.map(record => ({
json: record
}));

const records = $input.all().map(i => i.json);

const filteredRecords = records.filter(r => r.persona_id === 'pt_001');

const weeks = {};
for (const r of filteredRecords) {
  const w = r.week_number;
  if (!weeks[w]) weeks[w] = { total: 0, by_mode: {} };
  weeks[w].total += r.co2e_grams;
  weeks[w].by_mode[r.transport_mode] =
    (weeks[w].by_mode[r.transport_mode] || 0) + r.co2e_grams;
}

const sorted = Object.keys(weeks).map(Number).sort((a,b) => a-b);
const summaries = [];
let prevTotal = null;

for (const w of sorted) {
  const total = Math.round(weeks[w].total * 10) / 10;
  const dom = Object.entries(weeks[w].by_mode).sort((a,b) => b[1]-a[1])[0];
  let change = 0, trend = 'first week';
  if (prevTotal !== null && prevTotal > 0) {
    change = Math.round((total - prevTotal) / prevTotal * 1000) / 10;
    trend = change > 5 ? 'increasing' : change < -5 ? 'decreasing' : 'stable';
  }
  summaries.push({ week: w, total_co2e: total, by_mode: weeks[w].by_mode,
    dominant_mode: dom?.[0] || 'unknown',
    dominant_pct: dom ? Math.round(dom[1] / total * 100) : 0,
    prev_total: prevTotal, change_pct: change, trend });
  prevTotal = total;
}

const latest = summaries[summaries.length - 1];
return [{ json: { records: filteredRecords, summaries, ...latest } }];

const OLLAMA_URL = 'http://host.docker.internal:11434/api/chat';
const MODEL = 'mistral';
const MAX_STEPS = 6;

const input = $input.first().json;

const records     = Array.isArray(input.records)   ? input.records   : [];
const summaries   = Array.isArray(input.summaries) ? input.summaries : [];
const targetWeek  = Number(input.week);
const alertMode   = input.alert_mode === true;
const tone        = input.tone || (alertMode ? 'urgent' : 'informative');
const contextNote = input.context_note || '';

if (!records.length)              throw new Error('ReAct Agent received no transport records');
if (!Number.isFinite(targetWeek)) throw new Error('ReAct Agent received an invalid target week');

// ─────────────────────────────────────────────────────────────
// EMISSION FACTOR KNOWLEDGE
// Used by fallback to give accurate mode-aware recommendations
// ─────────────────────────────────────────────────────────────
const LOW_EMISSION_MODES  = ['bicycle', 'walking', 'e_bicycle'];
const MED_EMISSION_MODES  = ['train', 'subway', 'tram', 'bus'];
const HIGH_EMISSION_MODES = ['car', 'car_shared', 'motorcycle', 'ev_car', 'taxi',
                              'flight_domestic', 'flight_short_haul', 'ferry'];

const EMISSION_FACTORS = {
  car: 170, car_shared: 85, train: 35.7, subway: 27.3,
  bus: 89, tram: 28.9, bicycle: 0, e_bicycle: 4.5,
  walking: 0, motorcycle: 103, ev_car: 47, taxi: 186,
  flight_domestic: 246, flight_short_haul: 151, ferry: 18.9
};

function getModeCategory(mode) {
  if (LOW_EMISSION_MODES.includes(mode))  return 'low';
  if (MED_EMISSION_MODES.includes(mode))  return 'medium';
  if (HIGH_EMISSION_MODES.includes(mode)) return 'high';
  return 'unknown';
}

// ─────────────────────────────────────────────────────────────
// DETERMINISTIC TOOLS
// ─────────────────────────────────────────────────────────────

function getWeeklySummary(weekNumber) {
  const week = Number(weekNumber);
  const weekRecords = records.filter(r => Number(r.week_number) === week);
  if (!weekRecords.length) return { error: `No data found for week ${week}` };

  let total = 0;
  const byMode = {};
  for (const r of weekRecords) {
    const e = Number(r.co2e_grams) || 0;
    total += e;
    byMode[r.transport_mode] = (byMode[r.transport_mode] || 0) + e;
  }

  const sorted   = Object.entries(byMode).sort((a, b) => b[1] - a[1]);
  const dominant = sorted[0] || ['unknown', 0];

  return {
    week,
    total_co2e:    Math.round(total * 10) / 10,
    trip_count:    weekRecords.length,
    by_mode:       Object.fromEntries(sorted.map(([m, v]) => [m, Math.round(v * 10) / 10])),
    dominant_mode: dominant[0],
    dominant_pct:  total > 0 ? Math.round((dominant[1] / total) * 1000) / 10 : 0
  };
}

function getTopTrips(weekNumber, count = 3) {
  const week  = Number(weekNumber);
  const limit = Math.max(1, Number(count) || 3);
  const top   = records
    .filter(r => Number(r.week_number) === week)
    .sort((a, b) => Number(b.co2e_grams) - Number(a.co2e_grams))
    .slice(0, limit);

  return {
    week,
    top_trips: top.map(r => ({
      persona_id:  r.persona_id,
      date:        r.date,
      mode:        r.transport_mode,
      distance_km: Number(r.distance_km),
      co2e_grams:  Number(r.co2e_grams),
      origin:      r.origin      || '',
      destination: r.destination || ''
    }))
  };
}

function compareWeeks(firstWeek, secondWeek) {
  const w1 = getWeeklySummary(firstWeek);
  const w2 = getWeeklySummary(secondWeek);
  if (w1.error || w2.error) return { error: 'One or both weeks not found' };

  const diff      = w2.total_co2e - w1.total_co2e;
  const changePct = w1.total_co2e > 0
    ? Math.round((diff / w1.total_co2e) * 1000) / 10
    : null;

  let trend = 'stable';
  if (changePct !== null) {
    if (changePct >  5) trend = 'increasing';
    if (changePct < -5) trend = 'decreasing';
  }

  return {
    week1:            { week: w1.week, total_co2e: w1.total_co2e },
    week2:            { week: w2.week, total_co2e: w2.total_co2e },
    difference_gco2e: Math.round(diff * 10) / 10,
    change_pct:       changePct,
    trend
  };
}

function dispatchTool(name, args) {
  if (name === 'get_weekly_summary') return getWeeklySummary(args[0]);
  if (name === 'get_top_trips')      return getTopTrips(args[0], args[1]);
  if (name === 'compare_weeks')      return compareWeeks(args[0], args[1]);
  return { error: `Unknown tool: ${name}` };
}

function parseAction(text) {
  const match = text.match(/Action:\s*(\w+)\(([^)]*)\)/i);
  if (!match) return null;
  const args = match[2]
    .split(',')
    .map(v => v.trim())
    .filter(v => v.length > 0)
    .map(v => { const n = Number(v); return Number.isFinite(n) ? n : v; });
  return { name: match[1], args };
}

function extractRecommendations(text) {
  const marker = 'FINAL RECOMMENDATIONS:';
  const idx    = text.toUpperCase().indexOf(marker);
  if (idx === -1) return null;

  const body = text.substring(idx + marker.length).trim();
  if (!body) return null;

  const hasNumbered = /[1-3][.)]\s+\S/.test(body);
  return hasNumbered ? body : null;
}

// ─────────────────────────────────────────────────────────────
// GROUNDED FALLBACK — mode-aware, never suggests a mode
// the persona already uses as their primary mode
// ─────────────────────────────────────────────────────────────
function buildFallback() {
  const summary  = getWeeklySummary(targetWeek);
  const topTrips = getTopTrips(targetWeek, 3);
  const topTrip  = topTrips.top_trips[0];
  const prevWeek = targetWeek - 1;
  const comparison = prevWeek > 0 ? compareWeeks(prevWeek, targetWeek) : null;

  // Find which modes the persona actually uses this week
  const modesUsed    = Object.keys(summary.by_mode || {});
  const domMode      = summary.dominant_mode;
  const domCategory  = getModeCategory(domMode);
  const topTripMode  = topTrip?.mode || domMode;
  const topCategory  = getModeCategory(topTripMode);

  // ── Recommendation 1 — based on dominant mode category ──────────────────
  let r1;
  if (domCategory === 'high') {
    r1 = `1. Prioritise reducing ${domMode.replace(/_/g,' ')} journeys — this mode generated ` +
         `${summary.dominant_pct}% of Week ${targetWeek} emissions ` +
         `(${(summary.by_mode[domMode] || 0).toLocaleString()} gCO₂e). ` +
         `Switching even one day per week to train or bus makes a measurable difference.`;
  } else if (domCategory === 'medium') {
    // Already on public transport — suggest active travel for short legs
    const highModes = modesUsed.filter(m => getModeCategory(m) === 'high');
    if (highModes.length > 0) {
      r1 = `1. Your main mode (${domMode}) is already low-emission. ` +
           `Focus on reducing the remaining ${highModes.join(', ')} trips ` +
           `which produce far more CO₂e per km.`;
    } else {
      r1 = `1. Your transport mix is already sustainable — ${domMode} generates only ` +
           `${EMISSION_FACTORS[domMode] || '?'} gCO₂e/km. ` +
           `Consider replacing any short legs with walking or cycling to reach zero emissions on those trips.`;
    }
  } else {
    // Low emission dominant mode — truly green profile
    r1 = `1. Excellent — your dominant mode (${domMode}) produces zero direct emissions. ` +
         `Check if any remaining motorised trips can also be replaced with cycling or walking.`;
  }

  // ── Recommendation 2 — based on highest-emission single trip ────────────
  let r2;
  if (topTrip) {
    if (topCategory === 'high') {
      // Suggest switching to train
      const trainSaving = Math.round(topTrip.distance_km * 35.7);
      r2 = `2. The highest-emission trip this week was ${topTrip.distance_km} km ` +
           `by ${topTrip.mode} from ${topTrip.origin || 'origin'} to ` +
           `${topTrip.destination || 'destination'}, producing ${topTrip.co2e_grams} gCO₂e. ` +
           `Switching this trip to train reduces it to approximately ${trainSaving} gCO₂e — ` +
           `a saving of ${(topTrip.co2e_grams - trainSaving).toLocaleString()} gCO₂e per trip.`;
    } else if (topCategory === 'medium') {
      // Suggest replacing with active travel where feasible
      const walkSaving = topTrip.co2e_grams;
      r2 = `2. Your highest-emission trip was ${topTrip.distance_km} km by ${topTrip.mode} ` +
           `(${topTrip.co2e_grams} gCO₂e). If this leg is under 5 km, replacing it with ` +
           `cycling or walking saves the full ${walkSaving} gCO₂e at zero emission. ` +
           `If longer, check if a direct train connection exists to avoid the ${topTrip.mode} leg.`;
    } else {
      // Already zero emission
      r2 = `2. Your highest-emission trip (${topTrip.distance_km} km by ${topTrip.mode}) ` +
           `already produces near-zero emissions. Maintain this pattern — ` +
           `it sets a strong baseline for comparison in future weeks.`;
    }
  } else {
    r2 = `2. Review your trip data for Week ${targetWeek} and identify any car or taxi journeys ` +
         `that could be replaced with public transport or active travel.`;
  }

  // ── Recommendation 3 — week comparison ──────────────────────────────────
  let r3;
  if (comparison && !comparison.error && comparison.change_pct !== null) {
    if (comparison.change_pct > 0) {
      r3 = `3. Emissions were ${comparison.change_pct}% higher than Week ${prevWeek} ` +
           `(${comparison.week1.total_co2e.toLocaleString()} → ` +
           `${comparison.week2.total_co2e.toLocaleString()} gCO₂e). ` +
           `Identify which journeys changed between the two weeks and target those first.`;
    } else if (comparison.change_pct < 0) {
      r3 = `3. Emissions were ${Math.abs(comparison.change_pct)}% lower than Week ${prevWeek} ` +
           `(${comparison.week1.total_co2e.toLocaleString()} → ` +
           `${comparison.week2.total_co2e.toLocaleString()} gCO₂e). ` +
           `The travel choices that changed are worth protecting — keep this pattern next week.`;
    } else {
      r3 = `3. Emissions were essentially unchanged from Week ${prevWeek}. ` +
           `Set a small target: replace one higher-emission journey next week ` +
           `to begin a downward trend.`;
    }
  } else {
    r3 = `3. Use Week ${targetWeek} (${summary.total_co2e.toLocaleString()} gCO₂e) as your ` +
         `baseline. Compare it week by week to track whether your travel choices are improving.`;
  }

  return [r1, r2, r3].join('\n');
}

// ─────────────────────────────────────────────────────────────
// SYSTEM PROMPT — tells the AI about emission levels per mode
// so it never suggests reducing an already low-emission mode
// ─────────────────────────────────────────────────────────────
const toneGuide = alertMode
  ? 'Tone: URGENT. Lead with the dominant emission source and highest single trip.'
  : 'Tone: BALANCED. Focus on the most achievable change.';

const modeContext = `
EMISSION FACTORS (gCO₂e per km) — use these when evaluating modes:
  HIGH EMISSION  → car: 170, taxi: 186, motorcycle: 103, flight_domestic: 246
  MEDIUM EMISSION → bus: 89, ferry: 18.9, ev_car: 47
  LOW EMISSION   → train: 35.7, subway: 27.3, tram: 28.9, e_bicycle: 4.5
  ZERO EMISSION  → bicycle: 0, walking: 0

IMPORTANT RULES FOR RECOMMENDATIONS:
- Never tell someone to reduce a zero or low-emission mode (bicycle, walking, train, subway).
- If the dominant mode is already low-emission, recommend replacing any remaining HIGH-emission trips instead.
- If the person already uses subway, suggest cycling or walking for short legs as an upgrade — not switching to train (they may already use train).
- Always recommend switching HIGH-emission modes to lower ones, not the reverse.`.trim();

const systemPrompt = `You are a carbon footprint analysis agent.

Your task: investigate Week ${targetWeek} transport emissions and write 3 recommendations.

${contextNote ? 'Context: ' + contextNote : ''}
${toneGuide}

${modeContext}

TOOLS YOU MUST USE:
- get_weekly_summary(week_number)   → total CO2e and breakdown by mode
- get_top_trips(week_number, count) → highest-emission individual trips
- compare_weeks(week1, week2)       → compare two weeks

MANDATORY RULES:
1. Call get_weekly_summary(${targetWeek}) first.
2. Call get_top_trips(${targetWeek}, 3) second.
3. Only after at least 2 tool calls, write FINAL RECOMMENDATIONS.
4. Every number MUST come from a tool result. Never invent figures.
5. Never recommend reducing a low or zero emission mode.

TOOL CALL FORMAT:
Action: tool_name(argument1, argument2)

When ready:
FINAL RECOMMENDATIONS:
1. [specific, with real numbers from tool results]
2. [specific, with real numbers from tool results]
3. [specific, with real numbers from tool results]`.trim();

// ─────────────────────────────────────────────────────────────
// REACT LOOP
// ─────────────────────────────────────────────────────────────
const messages = [
  { role: 'system', content: systemPrompt },
  { role: 'user',   content: `Investigate Week ${targetWeek} transport emissions. Start by calling get_weekly_summary(${targetWeek}).` }
];

const auditTrace = [];
let finalRecommendations = null;
let agentSource          = 'ollama';
let toolCallsMade        = 0;

for (let step = 0; step < MAX_STEPS; step++) {
  let data;

  try {
    data = await this.helpers.httpRequest({
      method:  'POST',
      url:     OLLAMA_URL,
      headers: { 'Content-Type': 'application/json' },
      body: {
        model:   MODEL,
        messages,
        stream:  false,
        options: { temperature: 0.2, num_predict: 500 }
      },
      json:    true,
      timeout: 120000
    });
  } catch (error) {
    auditTrace.push({ step: step + 1, status: 'ollama_error', message: error.message });
    finalRecommendations = buildFallback();
    agentSource = 'fallback';
    break;
  }

  const responseText = data?.message?.content?.trim() || '';
  const extracted    = extractRecommendations(responseText);

  if (extracted) {
    if (toolCallsMade >= 2) {
      finalRecommendations = extracted;
      auditTrace.push({ step: step + 1, status: 'final_recommendations_accepted', tools_called: toolCallsMade });
      break;
    } else {
      messages.push({ role: 'assistant', content: responseText });
      messages.push({
        role:    'user',
        content: `You have not called any tools yet. You MUST call get_weekly_summary(${targetWeek}) before writing recommendations. Use the exact format: Action: get_weekly_summary(${targetWeek})`
      });
      auditTrace.push({ step: step + 1, status: 'recommendations_rejected_no_tools', tools_called: toolCallsMade });
      continue;
    }
  }

  const action = parseAction(responseText);

  if (!action) {
    messages.push({ role: 'assistant', content: responseText });
    messages.push({
      role:    'user',
      content: `No valid tool call detected. Use exactly: Action: get_weekly_summary(${targetWeek})`
    });
    auditTrace.push({ step: step + 1, status: 'invalid_tool_call' });
    continue;
  }

  const observation = dispatchTool(action.name, action.args);
  toolCallsMade++;

  auditTrace.push({ step: step + 1, tool: action.name, arguments: action.args, observation });

  messages.push({ role: 'assistant', content: `Action: ${action.name}(${action.args.join(', ')})` });
  messages.push({
    role:    'user',
    content: `Observation:\n${JSON.stringify(observation, null, 2)}\n\n${
      toolCallsMade >= 2
        ? 'You have called ' + toolCallsMade + ' tools. You may now write FINAL RECOMMENDATIONS.'
        : 'Good. Now call get_top_trips(' + targetWeek + ', 3).'
    }`
  });
}

if (!finalRecommendations) {
  finalRecommendations = buildFallback();
  agentSource = 'fallback';
  auditTrace.push({ status: 'max_steps_reached_using_fallback', tools_called: toolCallsMade });
}

return [{
  json: {
    ...input,
    recommendations:       finalRecommendations,
    reasoning_trace:       auditTrace,
    alert_mode:            alertMode,
    tone,
    recommendation_source: agentSource,
    tools_called:          toolCallsMade
  }
}];

const d = $input.first().json;
const dom = d.dominant_mode.replace(/_/g,' ').replace(/ \w/g, c=>c.toUpperCase());
const message = `⚠️ EMISSIONS ALERT — Week ${d.week}

Emissions rose ${d.change_pct}% this week — immediate action recommended.

Total:       ${d.total_co2e.toLocaleString()} gCO₂e
Last week:   ${d.prev_total ? d.prev_total.toLocaleString() + ' gCO₂e' : 'N/A'}
Main source: ${dom} (${d.dominant_pct}% of emissions)

📋 Priority Actions:

${d.recommendations}

— Carbon Footprint AI Assistant | DEFRA 2023 factors`;
return [{json:{message}}];

const d = $input.first().json;
const dom = d.dominant_mode.replace(/_/g,' ').replace(/ \w/g, c=>c.toUpperCase());
const trendLine = d.trend==='first week'?'First week — baseline established.'
  :d.trend==='increasing'?`▲ Up ${d.change_pct}% from last week`
  :d.trend==='decreasing'?`▼ Down ${Math.abs(d.change_pct)}% from last week`
  :`→ Stable vs last week (${d.change_pct>=0?'+':''}${d.change_pct}%)`;
const message = `🌍 Weekly Carbon Briefing — Week ${d.week}

Total: ${d.total_co2e.toLocaleString()} gCO₂e
${trendLine}
Main source: ${dom} (${d.dominant_pct}% of emissions)

📋 Recommendations:

${d.recommendations}

— Carbon Footprint AI Assistant | DEFRA 2023 factors`;
return [{json:{message}}];
